SELECT * FROM video_danmaku 
WHERE video_url = #{videoUrl}
  AND status = 1
  AND time >= #{fromTime}
  AND time <= #{toTime}
ORDER BY time ASC

SELECT * FROM video_danmaku 
WHERE video_url = #{videoUrl}
  AND status = 1
ORDER BY create_time DESC
LIMIT #{limit}

SELECT * FROM video_danmaku


        AND video_url = #{params.videoUrl}


        AND user_id = #{params.userId}


        AND article_id = #{params.articleId}


        AND status = #{params.status}


        AND content LIKE '%' || #{params.keyword} || '%'


ORDER BY create_time DESC

SELECT * FROM video_danmaku
WHERE article_id = #{articleId}
  AND video_url = #{videoUrl}
  AND time >= #{fromTime}
  AND time <= #{toTime}
  AND status = 1
ORDER BY time ASC

SELECT * FROM video_danmaku
WHERE article_id = #{articleId}
  AND video_url = #{videoUrl}
  AND status = 1
ORDER BY create_time DESC
LIMIT #{limit}

SELECT COUNT(*) FROM video_danmaku 
WHERE video_url = #{videoUrl}
  AND status = 1

SELECT COUNT(*) FROM video_danmaku
WHERE article_id = #{articleId}
  AND video_url = #{videoUrl}
  AND status = 1
